@app.cell
def _():
    # CORE_START: authoritative interval engine, also tested by test_science.py.
    import csv
    import hashlib
    import io
    import math
    import re
    from collections import Counter

    REVISION = "6b898ccc43d10d25b230fb09e22a6e30c30022b5"
    DATA_URL = (
        "https://huggingface.co/datasets/openadmet/"
        "openadmet-expansionrx-challenge-data/resolve/" + REVISION
        + "/expansion_data_raw.csv"
    )
    SOURCE_MD5 = "27fae3d509fb1d9fd97cc94a4c9cccec"
    ENDPOINTS = {
        "ksol": {"label": "Kinetic solubility", "column": "KSOL", "unit": "µM", "direction": "min", "default": 10.0,
                 "aliases": ["ksol", "kineticsolubility", "kineticsolubilityksol"], "domain": (0, math.inf)},
        "hlm": {"label": "Human microsomal clearance", "column": "HLM CLint", "unit": "mL/min/kg", "direction": "max", "default": 50.0,
                "aliases": ["hlmclint", "hlm", "humanlivermicrosomalclint"], "domain": (0, math.inf)},
        "papp": {"label": "Caco-2 permeability A→B", "column": "Caco-2 Permeability Papp A>B", "unit": "10⁻⁶ cm/s", "direction": "min", "default": 1.0,
                 "aliases": ["caco2permeabilitypappab", "caco2pappab", "pappab", "caco2pappa2b"], "domain": (0, math.inf)},
        "efflux": {"label": "Caco-2 efflux ratio", "column": "Caco-2 Permeability Efflux", "unit": "ratio", "direction": "max", "default": 3.0,
                   "aliases": ["caco2permeabilityefflux", "caco2effluxratio", "effluxratio", "caco2efflux"], "domain": (0, math.inf)},
    }
    MISSING_TOKENS = {"", "nan", "na", "n/a", "none", "null", "nd", "not tested", "-", "--"}


    def normalize_header(value):
        return re.sub(r"[^a-z0-9]", "", str(value).lower())


    def parse_measurement(raw, modifier=None):
        """Return a bounded/open interval, or unresolved evidence with a reason."""
        text = "" if raw is None else str(raw).strip()
        original = text
        if text.lower() in MISSING_TOKENS:
            return {"raw": original, "kind": "missing", "reason": "No measurement", "lo": None, "hi": None, "lo_open": False, "hi_open": False}
        mod = "" if modifier is None else str(modifier).strip()
        if mod.lower() in MISSING_TOKENS:
            mod = ""
        text = text.replace("≤", "<=").replace("≥", ">=").replace("−", "-")
        if mod:
            mod = mod.replace("≤", "<=").replace("≥", ">=")
            if mod not in {"=", "<", "<=", ">", ">="} or re.match(r"^[<>=]", text):
                return {"raw": f"{modifier} {original}".strip(), "kind": "unparsed", "reason": "Ambiguous qualifier", "lo": None, "hi": None, "lo_open": False, "hi_open": False}
            text = mod + text
        match = re.fullmatch(r"\s*(<=|>=|<|>|=)?\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*", text)
        if not match:
            return {"raw": (mod + original), "kind": "unparsed", "reason": "Unrecognized measurement", "lo": None, "hi": None, "lo_open": False, "hi_open": False}
        op, number = match.groups()
        value = float(number)
        if not math.isfinite(value):
            return {"raw": text, "kind": "unparsed", "reason": "Non-finite measurement", "lo": None, "hi": None, "lo_open": False, "hi_open": False}
        op = op or "="
        return {"raw": text, "kind": "exact" if op == "=" else "censored", "reason": "Measured" if op == "=" else "Assay limit",
                "lo": value if op in {"=", ">", ">="} else -math.inf,
                "hi": value if op in {"=", "<", "<="} else math.inf,
                "lo_open": op == ">", "hi_open": op == "<"}


    def apply_domain(measurement, key):
        """Check physical plausibility; don't invent an exact value at a limit."""
        m = dict(measurement)
        if m["lo"] is None:
            return m
        low, high = ENDPOINTS[key]["domain"]
        if m["hi"] < low or (m["hi"] == low and m["hi_open"]) or m["lo"] > high:
            m.update(kind="invalid", reason="Outside endpoint domain", lo=None, hi=None)
            return m
        if m["lo"] < low:
            m.update(lo=low, lo_open=False)
        if m["hi"] > high:
            m.update(hi=high, hi_open=False)
        return m


    def classify_measurement(measurement, direction, threshold):
        """Inclusive pass gates: x >= threshold or x <= threshold."""
        t = float(threshold)
        if not math.isfinite(t) or direction not in {"min", "max"}:
            raise ValueError("A finite threshold and direction min/max are required")
        if measurement["lo"] is None:
            return "unresolved"
        lo, hi = measurement["lo"], measurement["hi"]
        if direction == "min":
            if lo >= t:
                return "pass"
            if hi < t or (hi == t and measurement["hi_open"]):
                return "fail"
        else:
            if hi <= t:
                return "pass"
            if lo > t or (lo == t and measurement["lo_open"]):
                return "fail"
        return "unresolved"


    def source_schema(fieldnames):
        """Find numeric and optional qualifier columns; reject ambiguous schemas."""
        if len(set(fieldnames)) != len(fieldnames):
            raise ValueError("Duplicate CSV headers; inspect the source before parsing")
        normalized = {}
        for name in fieldnames:
            normalized.setdefault(normalize_header(name), []).append(name)
        def find_one(aliases, required=True):
            matches = list(dict.fromkeys(n for a in aliases for n in normalized.get(a, [])))
            if len(matches) > 1 or (required and len(matches) != 1):
                raise ValueError(f"Unrecognized/ambiguous schema for {aliases}: {matches}; columns={fieldnames}")
            return matches[0] if matches else None
        schema = {"id": find_one(["moleculename", "moleculeid", "compoundid", "name"]),
                  "smiles": find_one(["smiles", "standardizedsmiles"]), "endpoints": {}}
        for key, spec in ENDPOINTS.items():
            column = find_one(spec["aliases"])
            base = normalize_header(column)
            modifier = find_one([base + suffix for suffix in ["modifier", "mod", "qualifier", "operator", "relation"]]
                                + [prefix + base for prefix in ["modifier", "mod", "qualifier"]], required=False)
            schema["endpoints"][key] = {"value": column, "modifier": modifier}
        return schema


    def records_from_csv(data):
        """Keep published molecule IDs; don't average repeated or censored assays."""
        reader = csv.DictReader(io.StringIO(data.decode("utf-8-sig") if isinstance(data, bytes) else data))
        if not reader.fieldnames:
            raise ValueError("Empty CSV")
        schema = source_schema(reader.fieldnames)
        records, seen, raw_rows, duplicates = [], {}, 0, 0
        for row in reader:
            raw_rows += 1
            if None in row or any(value is None for value in row.values()):
                raise ValueError(f"Malformed CSV row {raw_rows + 1}")
            compound_id = (row[schema["id"]] or "").strip()
            smiles = (row[schema["smiles"]] or "").strip()
            if not compound_id:
                raise ValueError(f"Missing molecule identifier at row {raw_rows + 1}")
            signature = tuple(row.items())
            if compound_id in seen:
                if seen[compound_id] == signature:
                    duplicates += 1
                    continue
                raise ValueError(f"Conflicting repeated molecule ID {compound_id}; inspect the source before aggregation")
            seen[compound_id] = signature
            measurements = {}
            for key, cols in schema["endpoints"].items():
                m = parse_measurement(row[cols["value"]], row[cols["modifier"]] if cols["modifier"] else None)
                measurements[key] = apply_domain(m, key)
            records.append({"id": compound_id, "smiles": smiles, "measurements": measurements})
        if not records:
            raise ValueError("Dataset has no records")
        diagnostics = {"raw_rows": raw_rows, "molecule_ids": len(records), "identical_rows_removed": duplicates, "schema": schema,
                       "measurement_kinds": {k: dict(Counter(r["measurements"][k]["kind"] for r in records)) for k in ENDPOINTS},
                       "sha256": hashlib.sha256(data if isinstance(data, bytes) else data.encode()).hexdigest()}
        return records, diagnostics


    def evaluate_records(records, enabled, thresholds, hide_censored=False):
        """All gates must pass. One failure suffices; every other case is unresolved."""
        if not enabled or len(set(enabled)) != len(enabled) or any(k not in ENDPOINTS for k in enabled):
            raise ValueError("Select one or more distinct known endpoints")
        results = []
        for record in records:
            gates = {}
            for key in enabled:
                m = record["measurements"][key]
                if hide_censored and m["kind"] == "censored":
                    state = "unresolved"
                else:
                    state = classify_measurement(m, ENDPOINTS[key]["direction"], thresholds[key])
                gates[key] = state
            status = "fail" if "fail" in gates.values() else ("pass" if all(s == "pass" for s in gates.values()) else "unresolved")
            results.append({"id": record["id"], "status": status, "gates": gates})
        return results


    def summarize(results):
        counts = Counter(r["status"] for r in results)
        n = len(results)
        return {"n": n, "pass": counts["pass"], "fail": counts["fail"], "unresolved": counts["unresolved"],
                "lower": counts["pass"], "upper": counts["pass"] + counts["unresolved"],
                "complete_decisions": counts["pass"] + counts["fail"]}


    def assay_priority(results, enabled):
        """Count potentially decisive assays, not expected utility or success odds.

    Single blocker: resolving that gate would settle the compound either way.
    Any blocker: a failure could settle it; a pass may leave other unknown gates.
    """
        counts = {key: {"single_blocker": 0, "any_blocker": 0} for key in enabled}
        for result in results:
            if result["status"] != "unresolved":
                continue
            unknowns = [key for key, status in result["gates"].items() if status == "unresolved"]
            for key in unknowns:
                counts[key]["any_blocker"] += 1
                counts[key]["single_blocker"] += len(unknowns) == 1
        return [{"endpoint": key, **value} for key, value in sorted(counts.items(), key=lambda kv: (-kv[1]["single_blocker"], -kv[1]["any_blocker"], kv[0]))]


    def first_failure_attribution(results, order):
        """A waterfall's attribution depends on order; its final intersection doesn't."""
        attribution = {key: 0 for key in order}
        for result in results:
            for key in order:
                if result["gates"][key] == "fail":
                    attribution[key] += 1
                    break
        return [{"endpoint": key, "first_fail": attribution[key]} for key in order]


    def stringify_interval(m):
        if m["lo"] is None:
            return m["reason"]
        if m["lo"] == m["hi"]:
            return f"{{{m['lo']:g}}}"
        low = "−∞" if math.isinf(m["lo"]) else f"{m['lo']:g}"
        high = "∞" if math.isinf(m["hi"]) else f"{m['hi']:g}"
        return ("(" if m["lo_open"] or math.isinf(m["lo"]) else "[") + low + ", " + high + (")" if m["hi_open"] or math.isinf(m["hi"]) else "]")
    # CORE_END
    return (
        DATA_URL,
        ENDPOINTS,
        REVISION,
        SOURCE_MD5,
        assay_priority,
        evaluate_records,
        first_failure_attribution,
        hashlib,
        records_from_csv,
        stringify_interval,
        summarize,
    )


