@app.cell
def _(mo):
    mo.md("""
    **The question:** how do missing and censored measurements change the set of molecules
    we can certify against the same screening goals?

    **Teaching example (invented values):** imagine requiring solubility **≥10 µM**.
    A reported value **>100 µM** already establishes
    a pass; **<5 µM** establishes a failure. **<20 µM** remains unresolved at this threshold.
    None of these observations is an exact measurement at its assay limit.

    We use four endpoints from ExpansionRx's released campaigns: kinetic solubility,
    human liver microsomal clearance, Caco-2 permeability A→B, and Caco-2 efflux ratio.
    The targets below are **editable teaching examples**, not universal drug-selection
    criteria. Passing them does not establish efficacy, safety, or clinical suitability.
    """)
    return


@app.cell
def _(DATA_URL, SOURCE_MD5, hashlib, os, pathlib, urllib):
    # Embedded bytes, when present, are added by validate_full.py after source verification.
    embedded_raw_b64 = ""
    def load_source_bytes():
        if embedded_raw_b64:
            import base64
            import zlib
            payload = zlib.decompress(base64.b64decode(embedded_raw_b64))
            origin = "Embedded verified source snapshot"
        else:
            candidates = []
            if os.environ.get("MISSING_MOLECULES_CSV"):
                candidates.append(pathlib.Path(os.environ["MISSING_MOLECULES_CSV"]))
            candidates.extend([pathlib.Path("data/expansion_data_raw.csv"), pathlib.Path("expansion_data_raw.csv")])
            local = next((p for p in candidates if p.is_file()), None)
            if local:
                payload = local.read_bytes()
                origin = "Verified local source snapshot"
            else:
                request = urllib.request.Request(DATA_URL, headers={"User-Agent": "MissingMolecules/1.0"})
                with urllib.request.urlopen(request, timeout=45) as response:
                    payload = response.read()
                origin = "Pinned OpenADMET source download"
        actual = hashlib.md5(payload).hexdigest()
        if actual != SOURCE_MD5:
            raise ValueError(f"Source checksum mismatch ({actual}); inspect the source before changing the expected checksum")
        return payload, origin
    raw_data, source_origin = load_source_bytes()
    return raw_data, source_origin


@app.cell
def _(Chem, functools, raw_data, rdMolDraw2D, records_from_csv):
    source_records, source_audit = records_from_csv(raw_data)
    molecule_cache = {}
    records = []
    invalid_structure_ids = []
    canonical_groups = {}
    salt_ids = []
    for _record in source_records:
        _mol = Chem.MolFromSmiles(_record["smiles"])
        if _mol is None or _mol.GetNumAtoms() == 0:
            invalid_structure_ids.append(_record["id"])
            continue
        _canonical = Chem.MolToSmiles(_mol, isomericSmiles=True)
        canonical_groups.setdefault(_canonical, []).append(_record["id"])
        if len(Chem.GetMolFrags(_mol)) > 1:
            salt_ids.append(_record["id"])
        molecule_cache[_record["id"]] = _mol
        records.append(_record)
    if not records:
        raise ValueError("No valid chemical structures in the verified source")
    record_by_id = {r["id"]: r for r in records}
    @functools.lru_cache(maxsize=256)
    def draw_structure(compound_id):
        mol = Chem.Mol(molecule_cache[compound_id])
        drawer = rdMolDraw2D.MolDraw2DSVG(280, 150)
        drawer.drawOptions().clearBackground = False
        drawer.DrawMolecule(mol)
        drawer.FinishDrawing()
        svg = drawer.GetDrawingText()
        return svg[svg.index("<svg"):].replace("svg:", "")
    chemistry_audit = {"valid_molecule_ids": len(records), "invalid_structure_ids": invalid_structure_ids,
                       "multi_fragment_ids": salt_ids, "distinct_isomeric_structures": len(canonical_groups),
                       "repeated_structure_groups": sum(len(ids) > 1 for ids in canonical_groups.values()),
                       "repeated_structure_ids": {smiles: ids for smiles, ids in canonical_groups.items() if len(ids) > 1}}
    return chemistry_audit, draw_structure, record_by_id, records, source_audit


