@app.cell
def _(ENDPOINTS, mo):
    enabled_control = mo.ui.multiselect(options={spec["label"]: key for key, spec in ENDPOINTS.items()},
                                        value=[ENDPOINTS[k]["label"] for k in ["ksol", "hlm", "papp"]], label="Required endpoints", full_width=True)
    ksol_control = mo.ui.slider(start=0, stop=200, step=1, value=10, label="Solubility ≥ (µM)", show_value=True, full_width=True)
    hlm_control = mo.ui.slider(start=0, stop=300, step=5, value=50, label="HLM clearance ≤ (mL/min/kg)", show_value=True, full_width=True)
    papp_control = mo.ui.slider(start=0, stop=20, step=0.5, value=1, label="Permeability ≥ (10⁻⁶ cm/s)", show_value=True, full_width=True)
    efflux_control = mo.ui.slider(start=0, stop=20, step=0.5, value=3, label="Efflux ratio ≤", show_value=True, full_width=True)
    hide_censored_control = mo.ui.checkbox(value=False, label="Experiment: discard censored measurements")
    _threshold_grid = mo.Html('<div class="mm-control-grid">' + ''.join('<div>' + mo.as_html(_control).text + '</div>' for _control in [ksol_control, hlm_control, papp_control, efflux_control]) + '</div>')
    mo.vstack([mo.Html('<div class="mm-section">01 · Define the screening question</div>'), enabled_control,
               _threshold_grid, hide_censored_control])
    return (
        efflux_control,
        enabled_control,
        hide_censored_control,
        hlm_control,
        ksol_control,
        papp_control,
    )


@app.cell
def _(
    efflux_control,
    enabled_control,
    hlm_control,
    ksol_control,
    mo,
    papp_control,
):
    enabled = list(enabled_control.value)
    mo.stop(not enabled, mo.md("Select at least one endpoint to define a screening question."))
    thresholds = {"ksol": float(ksol_control.value), "hlm": float(hlm_control.value),
                  "papp": float(papp_control.value), "efflux": float(efflux_control.value)}
    return enabled, thresholds


@app.cell
def _(
    enabled,
    evaluate_records,
    hide_censored_control,
    records,
    summarize,
    thresholds,
):
    interval_results = evaluate_records(records, enabled, thresholds)
    exact_only_results = evaluate_records(records, enabled, thresholds, hide_censored=True)
    results = exact_only_results if hide_censored_control.value else interval_results
    evidence_summary = summarize(results)
    interval_summary = summarize(interval_results)
    exact_summary = summarize(exact_only_results)
    return evidence_summary, exact_summary, interval_summary, results


