@app.cell
def _(anywidget, traitlets):
    class EvidenceBoard(anywidget.AnyWidget):
        _esm = "// Purpose-built anywidget: interval evidence, linked structures, and gate-order experiment.\nexport default {\n  render({model, el}) {\n    const root = el.attachShadow({mode: 'open'});\n    const css = document.createElement('style');\n    css.textContent = `\n      :host{display:block;color:#17343b;font-family:Inter,ui-sans-serif,system-ui,sans-serif}\n      *{box-sizing:border-box}button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #156a73;outline-offset:3px}\n      .board{border:1px solid #c9dad9;background:#f5f8f5;border-radius:20px;padding:24px}\n      .eyebrow{font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:#48676c;font-weight:750}\n      h2{font-size:25px;letter-spacing:-.035em;margin:8px 0 6px;font-weight:650}.subtitle{font-size:13px;line-height:1.55;color:#536c70;margin:0 0 20px}\n      .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:white;border:1px solid #dde7e3;padding:14px;border-radius:12px}\n      .metric strong{font-size:30px;display:block;letter-spacing:-.05em}.metric span{font-size:12px;color:#516c71}.pass{color:#14664f}.fail{color:#a83d44}.unresolved{color:#8a620d}\n      .bar{display:flex;width:100%;height:13px;border-radius:8px;overflow:hidden;background:#e8eeeb;margin-top:18px}.bar>div{height:100%}\n      .range{font-size:14px;margin:12px 0 3px}.range strong{color:#0c565c}.fine{font-size:11px;color:#627b7f;line-height:1.6}\n      .divider{height:1px;background:#d7e3dd;margin:22px 0}.ordering{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}\n      .gate{display:flex;align-items:center;gap:6px;background:white;padding:7px;border:1px solid #d6e2df;border-radius:9px;font-size:11px}\n      .gate button{border:0;color:#1d555e;background:#eef4f0;border-radius:5px;padding:4px 7px}.gate button:disabled{opacity:.3;cursor:default}\n      .gate .name{background:transparent;padding:2px;font-weight:600}.gate.focus{border-color:#17717a;box-shadow:0 0 0 1px #17717a}\n      .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}\n      .card{background:white;border:1px solid #d9e5df;border-radius:12px;text-align:left;padding:12px;min-width:0;transition:transform .12s,border-color .12s}\n      .card:hover{transform:translateY(-2px);border-color:#6fa399}.card.selected{border:2px solid #146b72;padding:11px;box-shadow:0 5px 15px #1d555e12}\n      .card svg{display:block;width:100%;height:108px}.card-head{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px}.card .id{font-size:12px;font-weight:650}.badge{font-size:10px;font-weight:650;padding:3px 7px;border-radius:5px;background:#edf3ef;display:inline-block}\n      .mini{display:flex;gap:5px;margin-top:8px}.dot{width:8px;height:8px;border-radius:3px}.empty{padding:25px;font-size:13px;background:white;border-radius:12px;border:1px dashed #bbcfca}\n      .cards-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.live{font-size:11px;color:#587579}\n      @media(max-width:680px){.board{padding:16px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.metric strong{font-size:24px}.metric{padding:10px}}\n      @media(max-width:380px){.grid{grid-template-columns:1fr}}\n      @media(prefers-reduced-motion:reduce){.card{transition:none}.card:hover{transform:none}}\n    `;\n    root.append(css);\n    const host = document.createElement('div'); root.append(host);\n    const palette = {pass:'#16785c',fail:'#ba5158',unresolved:'#cb9b39'};\n    const label = {pass:'Evidence pass',fail:'Evidence fail',unresolved:'Unresolved'};\n    const fmt = n => Number(n || 0).toLocaleString('en-US');\n    const element = (tag, cls, text) => {\n      const e = document.createElement(tag); if(cls)e.className=cls;\n      if(text!==undefined)e.textContent=text; return e;\n    };\n    function update() {\n      host.replaceChildren();\n      const summary=model.get('summary') || {};\n      const rows=model.get('rows') || [];\n      const order=model.get('order') || [];\n      const endpoints=model.get('endpoints') || {};\n      const selected=model.get('selected_id') || '';\n      const focus=model.get('focus_endpoint') || '';\n      const board=element('section','board'); host.append(board);\n      board.append(element('div','eyebrow','Evidence board · live decisions'));\n      board.append(element('h2','', 'How many molecules actually qualify?'));\n      board.append(element('p','subtitle','Every enabled gate must pass. A single established failure settles a molecule; absent or inconclusive evidence keeps it unresolved.'));\n      const metrics=element('div','metrics');board.append(metrics);\n      for(const key of ['pass','fail','unresolved']){\n        const metric=element('div','metric');metric.append(element('strong',key,fmt(summary[key])));metric.append(element('span','',label[key]));metrics.append(metric);\n      }\n      const bar=element('div','bar');bar.setAttribute('role','img');bar.setAttribute('aria-label',`${fmt(summary.pass)} evidence pass, ${fmt(summary.fail)} evidence fail, ${fmt(summary.unresolved)} unresolved`);\n      for(const key of ['pass','unresolved','fail']){\n        const segment=element('div');segment.style.width=`${100*(summary[key] || 0)/Math.max(1,summary.n || 0)}%`;segment.style.background=palette[key];bar.append(segment);\n      }board.append(bar);\n      const range=element('p','range','Compatible with the available evidence: ');\n      range.append(element('strong','',`${fmt(summary.lower)}–${fmt(summary.upper)} qualifying molecule IDs`));board.append(range);\n      board.append(element('div','fine','This is a logical lower–upper bound, not a confidence interval or a forecast. The upper bound allows every unresolved gate to pass.'));\n      board.append(element('div','divider'));board.append(element('div','eyebrow','Experiment · reorder the gates'));\n      const ordering=element('div','ordering');board.append(ordering);\n      order.forEach((key,index)=>{\n        const gate=element('div','gate'+(focus===key?' focus':''));\n        const name=element('button','name',`${index+1}. ${endpoints[key]?.short || key}`);name.type='button';name.title='Focus the evidence detail on this assay';\n        name.addEventListener('click',()=>{model.set('focus_endpoint',key);model.save_changes();});gate.append(name);\n        for(const [delta,text] of [[-1,'←'],[1,'→']]){\n          const btn=element('button','',text);btn.type='button';btn.disabled=index+delta<0 || index+delta>=order.length;btn.setAttribute('aria-label',`Move ${endpoints[key]?.short || key} ${delta<0?'earlier':'later'}`);\n          btn.addEventListener('click',()=>{const next=[...order];[next[index],next[index+delta]]=[next[index+delta],next[index]];model.set('order',next);model.save_changes();});gate.append(btn);\n        }ordering.append(gate);\n      });\n      board.append(element('div','fine','Changing the order changes the first-failure attribution below. It cannot change the final all-gates decision.'));\n      board.append(element('div','divider'));\n      const head=element('div','cards-head');head.append(element('div','eyebrow','Click a molecule · inspect its evidence'));head.append(element('div','live',`${fmt(rows.length)} shown · use the filters above`));board.append(head);\n      const grid=element('div','grid');board.append(grid);\n      if(!rows.length)grid.append(element('div','empty','No molecule IDs match these display filters. The population counts above still use the full valid-structure dataset.'));\n      for(const row of rows){\n        const card=element('button','card'+(row.id===selected?' selected':''));card.type='button';card.setAttribute('aria-label',`${row.id}: ${label[row.status]}`);card.setAttribute('aria-pressed',String(row.id===selected));\n        const badge=element('span','badge '+row.status,label[row.status]);const header=element('div','card-head');header.append(element('span','id',row.id));header.append(badge);card.append(header);\n        if(row.svg){const structure=element('div');structure.innerHTML=row.svg;card.append(structure);}\n        const mini=element('div','mini');\n        for(const key of order){const dot=element('span','dot');dot.style.background=palette[row.gates[key]];dot.title=`${endpoints[key]?.short || key}: ${label[row.gates[key]]}`;mini.append(dot);}card.append(mini);\n        card.addEventListener('click',()=>{model.set('selected_id',row.id);model.save_changes();});grid.append(card);\n      }\n    }\n    const events=['summary','rows','order','selected_id','focus_endpoint','endpoints'];\n    for(const event of events)model.on('change:'+event,update);\n    update();\n    return ()=>{for(const event of events)model.off('change:'+event,update);};\n  }\n};\n"
        rows = traitlets.List(default_value=[]).tag(sync=True)
        summary = traitlets.Dict(default_value={}).tag(sync=True)
        endpoints = traitlets.Dict(default_value={}).tag(sync=True)
        order = traitlets.List(default_value=[]).tag(sync=True)
        selected_id = traitlets.Unicode("").tag(sync=True)
        focus_endpoint = traitlets.Unicode("").tag(sync=True)

    return (EvidenceBoard,)


@app.cell
def _(EvidenceBoard, mo):
    # Keep one widget model alive across reactive data changes.
    board = mo.ui.anywidget(EvidenceBoard())
    return (board,)


@app.cell
def _(
    ENDPOINTS,
    board,
    display_limit,
    draw_structure,
    enabled,
    evidence_summary,
    results,
    search_control,
    status_filter,
):
    _query = search_control.value.strip().lower()
    _rows = [r for r in results if (status_filter.value == "all" or r["status"] == status_filter.value) and _query in r["id"].lower()]
    _rows = sorted(_rows, key=lambda r: ({"unresolved": 0, "pass": 1, "fail": 2}[r["status"]], r["id"]))[:display_limit.value]
    _cards = [{**r, "svg": draw_structure(r["id"])} for r in _rows]
    _state = board.value
    _current_order = [k for k in _state.get("order", []) if k in enabled]
    _order = _current_order + [k for k in enabled if k not in _current_order]
    _card_ids = {r["id"] for r in _cards}
    _selected = _state.get("selected_id", "")
    _focus = _state.get("focus_endpoint", "")
    with board.widget.hold_sync():
        board.widget.rows = _cards
        board.widget.summary = evidence_summary
        board.widget.endpoints = {key: {"short": ENDPOINTS[key]["column"]} for key in enabled}
        board.widget.order = _order
        board.widget.selected_id = _selected if _selected in _card_ids else (_cards[0]["id"] if _cards else "")
        board.widget.focus_endpoint = _focus if _focus in enabled else enabled[0]
    board_data_ready = True
    board
    return (board_data_ready,)


@app.cell
def _(
    ENDPOINTS,
    board,
    board_data_ready,
    chemistry_audit,
    enabled,
    hide_censored_control,
    html,
    mo,
    record_by_id,
    results,
    stringify_interval,
    thresholds,
):
    assert board_data_ready
    selected_id = board.value.get("selected_id", "")
    focus_endpoint = board.value.get("focus_endpoint", enabled[0])
    _record = record_by_id.get(selected_id)
    if _record:
        _result = next(r for r in results if r["id"] == selected_id)
        _rows_html = []
        _identity_notes = []
        if selected_id in chemistry_audit["multi_fragment_ids"]:
            _identity_notes.append("Published multi-fragment structure retained; assay context is not reconstructed.")
        for _group in chemistry_audit["repeated_structure_ids"].values():
            if selected_id in _group:
                _identity_notes.append("Same canonical isomeric structure appears under IDs: " + ", ".join(_group))
        for _key in enabled:
            _m = _record["measurements"][_key]
            _spec = ENDPOINTS[_key]
            _gate = "≥" if _spec["direction"] == "min" else "≤"
            _note = "Discarded in this experiment" if hide_censored_control.value and _m["kind"] == "censored" else _m["reason"]
            _mark = " · focused" if _key == focus_endpoint else ""
            _rows_html.append(f'<tr><td>{html.escape(_spec["label"] + _mark)}</td><td>{html.escape(_m["raw"] or "Missing")}</td><td>{html.escape(stringify_interval(_m))}</td><td>{_gate} {thresholds[_key]:g} {html.escape(_spec["unit"])}</td><td class="{_result["gates"][_key]}">{_result["gates"][_key]}</td><td>{html.escape(_note)}</td></tr>')
        _detail = mo.Html('<section class="mm-panel mm-details"><strong>' + html.escape(selected_id)
            + '</strong> · molecule evidence<div class="mm-table-scroll" tabindex="0" role="region" aria-label="Molecule evidence table; scroll horizontally on narrow screens"><table class="mm-table"><thead><tr><th>Endpoint</th><th>Reported</th><th>Possible values</th><th>Gate</th><th>Decision</th><th>Evidence</th></tr></thead><tbody>'
            + ''.join(_rows_html) + '</tbody></table></div><p style="overflow-wrap:anywhere">SMILES: <code>' + html.escape(_record["smiles"]) + '</code></p>'
            + ''.join('<p>' + html.escape(_note) + '</p>' for _note in _identity_notes) + '</section>')
    else:
        _detail = mo.md("Choose a displayed molecule to inspect its evidence.")
    _detail
    return (focus_endpoint,)


@app.cell
def _(exact_summary, interval_summary, mo):
    _rescued_pass = interval_summary["pass"] - exact_summary["pass"]
    _rescued_fail = interval_summary["fail"] - exact_summary["fail"]
    _settled = _rescued_pass + _rescued_fail
    mo.vstack([mo.Html('<div class="mm-section">02 · What did cleaning the data erase?</div>'), mo.md(f"""
    Keeping the assay bounds settles **{_rescued_pass:,} additional passes** and
    **{_rescued_fail:,} additional failures** under your current gates.
    These decisions use information already present in the raw data; no model or imputation is involved.

    **Takeaway:** discarding assay limits makes **{_settled:,} of {interval_summary['n']:,}
    molecule-ID decisions unresolved** ({100 * _settled / interval_summary['n']:.1f}% of this population).
    Keeping the bounds narrows the compatible shortlist from
    **{exact_summary['lower']:,}–{exact_summary['upper']:,}** to
    **{interval_summary['lower']:,}–{interval_summary['upper']:,}**.
    The numbers follow the gates you choose; they describe this release and these illustrative
    thresholds, without modeling assay uncertainty beyond the published inequalities.

    A censored value can be sufficient evidence even when it is unsuitable as an exact
    regression target. Flip **“discard censored measurements”** above and watch the
    logical bounds widen or stay unchanged.
    """), mo.ui.table([
        {"Evidence policy": "Use exact values and assay bounds", "Established passes": interval_summary["pass"], "Established failures": interval_summary["fail"], "Unresolved": interval_summary["unresolved"], "Compatible shortlist": f'{interval_summary["lower"]}–{interval_summary["upper"]}'},
        {"Evidence policy": "Discard every censored value", "Established passes": exact_summary["pass"], "Established failures": exact_summary["fail"], "Unresolved": exact_summary["unresolved"], "Compatible shortlist": f'{exact_summary["lower"]}–{exact_summary["upper"]}'},
    ], selection=None)])
    return


@app.cell
def _(
    ENDPOINTS,
    board,
    board_data_ready,
    enabled,
    first_failure_attribution,
    mo,
    results,
):
    assert board_data_ready
    gate_order = list(board.value.get("order", enabled))
    if sorted(gate_order) != sorted(enabled):
        raise ValueError("Widget gate order must be a permutation of the enabled endpoints")
    attribution = first_failure_attribution(results, gate_order)
    mo.vstack([mo.Html('<div class="mm-section">03 · A liability waterfall can tell several stories</div>'), mo.md("""
    Use the arrow buttons on the evidence board to move an assay earlier or later.
    A molecule can fail several gates. A first-failure waterfall credits only the first
    failed gate it encounters, so its attribution can change while the final shortlist
    stays fixed. These are accounting choices, not causal explanations of molecular liability.
    """), mo.ui.table([{"Order": i + 1, "Assay": ENDPOINTS[row["endpoint"]]["label"], "Attributed first failures": row["first_fail"]} for i, row in enumerate(attribution)], selection=None)])
    return attribution, gate_order


@app.cell
def _(ENDPOINTS, assay_priority, enabled, focus_endpoint, mo, results):
    priorities = assay_priority(results, enabled)
    mo.vstack([mo.Html('<div class="mm-section">04 · Which measurement could settle a decision?</div>'), mo.md("""
    **Single unresolved gate:** resolving this one assay would settle that molecule's
    status under the current criteria, whether it passes or fails. Other unresolved
    gates can also matter: a failure could reject the molecule, while a pass might
    leave further assays to resolve.

    The counts below measure **decision opportunity**, not expected success, monetary
    value, or a guarantee that a repeated assay would return an uncensored result.
    """), mo.ui.table([{"Assay": ENDPOINTS[row["endpoint"]]["label"], "Only unresolved gate": row["single_blocker"], "Unresolved gate in otherwise viable IDs": row["any_blocker"], "Focused on board": row["endpoint"] == focus_endpoint} for row in priorities], selection=None)])
    return (priorities,)


@app.cell
def _(
    ENDPOINTS,
    attribution,
    enabled,
    evidence_summary,
    gate_order,
    hide_censored_control,
    json,
    mo,
    priorities,
    results,
    source_audit,
    thresholds,
):
    decision_export = {"source_sha256": source_audit["sha256"], "enabled_endpoints": enabled,
                       "thresholds": {k: {"value": thresholds[k], "unit": ENDPOINTS[k]["unit"], "direction": ENDPOINTS[k]["direction"]} for k in enabled},
                       "discard_censored": hide_censored_control.value, "summary": evidence_summary,
                       "gate_order": gate_order, "first_failure_attribution": attribution,
                       "assay_opportunity": priorities, "molecule_decisions": results,
                       "counting_unit": "published molecule IDs with valid nonempty RDKit structures",
                       "interpretation": "Logical evidence bounds under illustrative gates; no prediction or clinical certification"}
    mo.download(data=json.dumps(decision_export, indent=2).encode(), filename="my_evidence_question.json", label="Download this question and its results")
    return


@app.cell
def _(ENDPOINTS, chemistry_audit, mo, records, source_audit):
    _audit_table = [{"Endpoint": ENDPOINTS[key]["label"], **{kind: source_audit["measurement_kinds"][key].get(kind, 0) for kind in ["exact", "censored", "missing", "unparsed", "invalid"]}} for key in ENDPOINTS]
    _valid_audit_table = [{"Endpoint": ENDPOINTS[key]["label"], **{kind: sum(r["measurements"][key]["kind"] == kind for r in records) for kind in ["exact", "censored", "missing", "unparsed", "invalid"]}} for key in ENDPOINTS]
    mo.accordion({
        "Data provenance and chemistry audit": mo.vstack([mo.md(f"""
        Source: [ExpansionRx / OpenADMET full release](https://huggingface.co/datasets/openadmet/openadmet-expansionrx-challenge-data).
        Dataset DOI: [10.57967/hf/9687](https://doi.org/10.57967/hf/9687).
        License: **CC BY 4.0**. Credit: Expansion Therapeutics and the OpenADMET Consortium.
        Measurements and structures are redistributed unchanged when embedded; the decision annotations are this notebook's additions.

        **SHA-256:** `{source_audit['sha256']}`.
        Identical repeated source rows removed: **{source_audit['identical_rows_removed']}**.
        The parser checks IDs, expected columns, qualifiers, and non-finite or malformed values;
        ambiguous schemas and conflicting repeated IDs stop execution for inspection.

        RDKit parses the published SMILES and preserves stereochemistry in depictions.
        Multi-fragment IDs are retained and flagged: **{len(chemistry_audit['multi_fragment_ids'])}**.
        No salt stripping, tautomer merging, or averaging of repeated assays is performed.
        Published salts and tautomer forms may encode assay-specific context we cannot reconstruct;
        unspecified stereochemistry remains unspecified. No stereoisomer is invented.
        Distinct canonical isomeric structures: **{chemistry_audit['distinct_isomeric_structures']}**;
        structure groups with multiple IDs: **{chemistry_audit['repeated_structure_groups']}**.
        These grouped structures remain separate published IDs, so their decisions are not independent samples.
        """), mo.md(f"**All parsed source IDs ({source_audit['molecule_ids']:,}):**"),
        mo.ui.table(_audit_table, selection=None), mo.md(f"**Valid-structure analysis IDs ({len(records):,}):**"),
        mo.ui.table(_valid_audit_table, selection=None), mo.json(chemistry_audit)]),
        "What the bounds mean—and what this lab cannot establish": mo.md("""
        For each molecule, we evaluate the **set** of values compatible with each reported
        observation against inclusive gates (≥ or ≤). All gates must be established passes
        to certify a pass. Any established failure rejects the molecule. Everything else
        is unresolved. Missing, malformed, or physically invalid evidence never establishes a pass.

        The compatible shortlist has a lower bound equal to the established passes and an
        upper bound equal to passes plus unresolved IDs. These are logical identification
        bounds under the displayed assay evidence, not statistical confidence intervals.
        The upper bound permits all unresolved gates to pass jointly; chemistry correlations
        may make it loose. Experimental uncertainty beyond reported qualifiers is not modeled.

        This is a descriptive analysis of a selected set of drug-discovery campaigns.
        We do not infer that missingness is random, explain why an assay is absent, recommend
        clinical treatment, or demonstrate an improved predictive model. There is no
        train/test evaluation: the raw release is explored as one population.
        """),
        "AI use, contribution, and reproduce this notebook": mo.md("""
        **AI disclosure:** OpenAI ChatGPT/Codex assisted with concept development, Python,
        JavaScript, testing, and explanatory text. Harsh Pandey is responsible for final
        review and submission. The custom EvidenceBoard widget implements linked molecule
        inspection, interval bounds, and the gate-order experiment; it is developed for this notebook.
        No synthetic measurements are substituted for the released data.

        **Reproduce:** use a normal Python-backed molab session or run
        `uv run --with marimo marimo edit --sandbox missing_molecules.py`.
        The file declares its dependencies. Its source is pinned and checksum verified;
        a finalized copy embeds the verified raw CSV. Without embedded data it loads the
        local snapshot or downloads that same pinned release. Network failure is explicit.
        RDKit needs a standard Python runtime; this notebook is not advertised as WASM compatible.

        Suggested reader challenge: choose two endpoint gates, find a censored observation
        that settles a decision, then tighten the threshold until the same observation
        becomes unresolved. Explain the change using its possible-value interval.
        """)
    })
    return


if __name__ == "__main__":
    app.run()
